color-indigo-50);' '  --color-bg-error-base: var(--color-red-500);' '  --color-bg-error-base-hover: var(--color-red-600);' '  --color-bg-error-soft: color-mix(in srgb, var(--color-red-500) 12%, var(--color-white));' '  --color-bg-error-softest: color-mix(in srgb, var(--color-red-500) 6%, var(--color-white));' '  --color-bg-warning-base: var(--color-yellow-200);' '  --color-bg-warning-soft: color-mix(in srgb, var(--color-yellow-200) 18%, var(--color-white));' '  --color-bg-warning-softest: color-mix(in srgb, var(--color-yellow-200) 9%, var(--color-white));' '  --color-bg-success-base: var(--color-green-200);' '  --color-bg-success-soft: color-mix(in srgb, var(--color-green-200) 18%, var(--color-white));' '  --color-bg-success-softest: color-mix(in srgb, var(--color-green-200) 9%, var(--color-white));' '  --color-border-primary: var(--color-grey-300);' '  --color-border-brand: var(--color-indigo-800);' '  --color-border-brand-soft: var(--color-indigo-300);' '  --color-border-error: var(--color-red-500);' '  --color-border-media: #{utils.css-alpha(var(--color-white), 15%)};' '  --color-border-error-soft: #{utils.css-alpha(var(--color-text-error), 50%)};' '  --color-border-warning-soft: #{utils.css-alpha(var(--color-text-warning), 50%)};' '  --color-border-success-soft: var(--color-green-200);' '  --shadow-strength-primary: 30%;' '  --color-shadow-primary: #{utils.css-alpha(var(--color-blue-950), var(--shadow-strength-primary))};' '  --dropdown-shadow: 0 20px 25px -5px var(--color-shadow-primary), 0 8px 10px -6px var(--color-shadow-primary);' '  --overlay-icon-shadow: drop-shadow(0 0 8px var(--color-shadow-primary));' '  --color-graph-primary-stroke: var(--color-text-brand);' '  --color-graph-primary-fill: var(--color-bg-brand-softest);' '  --color-graph-warning-stroke: var(--color-text-warning);' '  --color-graph-warning-fill: var(--color-bg-warning-softest);' '  --color-graph-disabled-stroke: var(--color-text-disabled);' '  --color-graph-disabled-fill: var(--color-bg-disabled);' '  --rich-text-container-color: var(--color-indigo-200);' '  --rich-text-text-color: var(--color-grey-800);' '  --rich-text-decorations-color: var(--color-indigo-600);' '  input[type="radio"]:not(:disabled) {' '    appearance: none;' '    box-sizing: border-box;' '    border: 1px solid var(--color-bg-brand-base);' '    border-radius: 50%;' '    box-shadow: none;' '    background: var(--color-bg-primary);' '  }' '  input[type="radio"]:checked:not(:disabled) {' '    background: var(--color-bg-brand-base);' '    box-shadow: inset 0 0 0 4px var(--color-bg-primary);' '  }' '  input[type="radio"]:focus-visible {' '    outline: var(--outline-focus-default);' '    outline-offset: 2px;' '  }' '  .poll__option:not(.dialog-option):not(.disabled):not(:has(> input:disabled)) > .poll__input:not(.disabled) {' '    border: 1px solid var(--color-bg-brand-base);' '    background: var(--color-bg-primary);' '    box-shadow: none;' '  }' '  .poll__option:not(.dialog-option):not(.disabled):not(:has(> input:disabled)) > .poll__input:not(.disabled):is(:active, :focus, :hover) {' '    border-color: var(--color-bg-brand-base);' '    border-width: 1px;' '  }' '  .poll__option:not(.dialog-option):not(.disabled):not(:has(> input:disabled)) > .poll__input:not(.disabled).active:not(.checkbox) {' '    background: var(--color-bg-brand-base);' '    box-shadow: inset 0 0 0 4px var(--color-bg-primary);' '  }' '  .poll__option:not(.dialog-option):not(.disabled):not(:has(> input:disabled)) > .poll__input:not(.disabled).checkbox.active {' '    color: var(--color-text-primary);' '    background: var(--color-bg-primary);' '    box-shadow: none;' '  }' '  .poll__option:not(.dialog-option):not(.disabled):not(:has(> input:disabled)) > .poll__input:not(.disabled).checkbox.active::after {' '    content: "";' '    position: absolute;' '    top: 1px;' '    left: 5px;' '    width: 5px;' '    height: 9px;' '    border: solid currentColor;' '    border-width: 0 2px 2px 0;' '    transform: rotate(45deg);'