r-blue-900);' '  --color-bg-error-base: var(--color-red-400);' '  --color-bg-error-base-hover: var(--color-red-300);' '  --color-bg-error-soft: color-mix(in srgb, var(--color-red-400) 18%, var(--color-blue-950));' '  --color-bg-error-softest: color-mix(in srgb, var(--color-red-400) 10%, var(--color-blue-950));' '  --color-bg-warning-base: var(--color-yellow-200);' '  --color-bg-warning-soft: color-mix(in srgb, var(--color-yellow-200) 18%, var(--color-blue-950));' '  --color-bg-warning-softest: color-mix(in srgb, var(--color-yellow-200) 10%, var(--color-blue-950));' '  --color-bg-success-base: var(--color-green-200);' '  --color-bg-success-soft: color-mix(in srgb, var(--color-green-200) 18%, var(--color-blue-950));' '  --color-bg-success-softest: color-mix(in srgb, var(--color-green-200) 10%, var(--color-blue-950));' '  --color-border-primary: var(--color-blue-800);' '  --color-border-brand: var(--color-blue-200);' '  --color-border-brand-soft: var(--color-blue-700);' '  --color-border-error: var(--color-red-300);' '  --color-border-media: #{utils.css-alpha(var(--color-blue-50), 15%)};' '  --color-border-error-soft: #{utils.css-alpha(var(--color-border-error), 50%)};' '  --color-border-warning-soft: #{utils.css-alpha(var(--color-text-warning), 50%)};' '  --color-border-success-soft: var(--color-green-400);' '  --shadow-strength-primary: 80%;' '  --color-shadow-primary: #{utils.css-alpha(var(--color-blue-950), var(--shadow-strength-primary))};' '  --dropdown-shadow: 0 20px 25px -5px var(--color-shadow-primary), 0 8px 10px -6px var(--color-shadow-primary);' '  --overlay-icon-shadow: drop-shadow(0 0 8px var(--color-shadow-primary));' '  --color-graph-primary-stroke: var(--color-text-brand);' '  --color-graph-primary-fill: var(--color-bg-brand-softest);' '  --color-graph-warning-stroke: var(--color-text-warning);' '  --color-graph-warning-fill: var(--color-bg-warning-softest);' '  --color-graph-disabled-stroke: var(--color-text-disabled);' '  --color-graph-disabled-fill: var(--color-bg-disabled);' '  --rich-text-container-color: var(--color-blue-800);' '  --rich-text-text-color: var(--color-blue-100);' '  --rich-text-decorations-color: var(--color-blue-400);' '  .poll__option:not(.dialog-option):not(.disabled):not(:has(> input:disabled)) > .poll__input:not(.disabled) {' '    border: 1px solid var(--color-bg-brand-base);' '    background: var(--color-bg-primary);' '    box-shadow: none;' '  }' '  .poll__option:not(.dialog-option):not(.disabled):not(:has(> input:disabled)) > .poll__input:not(.disabled):is(:active, :focus, :hover) {' '    border-color: var(--color-bg-brand-base);' '    border-width: 1px;' '  }' '  .poll__option:not(.dialog-option):not(.disabled):not(:has(> input:disabled)) > .poll__input:not(.disabled).active:not(.checkbox) {' '    background: var(--color-blue-400);' '    box-shadow: inset 0 0 0 4px var(--color-bg-primary);' '  }' '  .poll__option:not(.dialog-option):not(.disabled):not(:has(> input:disabled)) > .poll__input:not(.disabled).checkbox.active {' '    color: var(--color-blue-400);' '    background: var(--color-bg-primary);' '    box-shadow: none;' '  }' '  .poll__option:not(.dialog-option):not(.disabled):not(:has(> input:disabled)) > .poll__input:not(.disabled).checkbox.active::after {' '    content: "";' '    position: absolute;' '    top: 1px;' '    left: 5px;' '    width: 5px;' '    height: 9px;' '    border: solid currentColor;' '    border-width: 0 2px 2px 0;' '    transform: rotate(45deg);' '  }' '  .logo--wordmark {' '    color: var(--color-white);' '  }' '}' '' '@mixin contrast-overrides {' '  --color-text-primary: var(--color-blue-50);' '  --color-text-status-links: var(--color-blue-400);' '  --color-bg-error-base: var(--color-red-300);' '  --color-bg-secondary: var(--color-blue-900);' '  --color-border-primary: var(--color-blue-600);' '}' > "$sakura_theme_dir/_dark.scss"
