printf '%s\n' '/* Shared controls for both Sakura themes. */' '' '::selection {' '  color: var(--sakura-selection-text);' '  background: var(--sakura-selection-bg);' '}' '' '.simple_form :is(input, textarea)::placeholder,' ':is(.layout-single-column, .layout-multiple-columns) :is(.search__input, .autosuggest-textarea__textarea, .spoiler-input__input, .emoji-mart-search input)::placeholder,' ':is(input, textarea)[class*="_comp_form_fields_text_input__input"]::placeholder {' '  color: var(--sakura-placeholder);' '  opacity: 1;' '}' '' '.simple_form :is(input, textarea, select):is(:autofill, :-webkit-autofill) {' '  box-shadow: 0 0 0 1000px var(--color-bg-overlay) inset;' '  -webkit-text-fill-color: var(--color-text-primary);' '  caret-color: var(--color-text-primary);' '}' '' '.simple_form input[type="file"]::file-selector-button {' '  margin-inline-end: 8px;' '  border: 1px solid var(--color-bg-brand-base);' '  border-radius: 4px;' '  padding: 6px 12px;' '  background: var(--color-bg-brand-base);' '  color: var(--color-text-on-brand-base);' '  font: inherit;' '  cursor: pointer;' '}' '' '.simple_form input[type="file"]:not(:disabled):is(:hover, :focus-visible)::file-selector-button {' '  border-color: var(--color-bg-brand-base-hover);' '  background: var(--color-bg-brand-base-hover);' '}' '' '.simple_form input[type="file"]:disabled::file-selector-button {' '  border-color: var(--color-bg-disabled);' '  background: var(--color-bg-disabled);' '  color: var(--color-text-on-disabled);' '  cursor: not-allowed;' '}' '' '.simple_form .input.radio_buttons .radio input[type="radio"],' 'input[type="radio"][class*="_comp_form_fields_radio_button__radioButton"] {' '  appearance: none;' '  box-sizing: border-box;' '  border: 1px solid var(--color-bg-brand-base);' '  border-radius: 50%;' '  background: var(--color-bg-primary);' '  box-shadow: none;' '}' '' '.simple_form .input.radio_buttons .radio input[type="radio"]:checked,' 'input[type="radio"][class*="_comp_form_fields_radio_